22	// Adapter implements domain.DbWorkspaceAdapter.
23	type Adapter struct {
24		pool *pgxpool.Pool
25		q    *database.Queries
26	}
27	
28	// New creates a new Adapter from an existing pgxpool.Pool.
29	func New(pool *pgxpool.Pool) *Adapter {
30		return &Adapter{pool: pool, q: database.New(pool)}
31	}
32	
33	// Connect creates a pgxpool.Pool from the given DATABASE_URL and returns a new Adapter.
34	func Connect(ctx context.Context, databaseURL string) (*Adapter, error) {
35		pool, err := pgxpool.New(ctx, databaseURL)
36		if err != nil {
37			return nil, fmt.Errorf("pgxpool.New: %w", err)
38		}
39		if err := pool.Ping(ctx); err != nil {
40			pool.Close()
41			return nil, fmt.Errorf("ping db: %w", err)
42		}
43		return New(pool), nil
44	}
45	
46	// Close releases the connection pool.
47	func (a *Adapter) Close() { a.pool.Close() }
48	
49	// ListWorkspaces returns summary rows for all saved workspaces.
50	func (a *Adapter) ListWorkspaces(ctx context.Context) ([]domain.WorkspaceSummary, error) {
51		rows, err := a.q.ListWorkspaces(ctx)
52		if err != nil {
53			return nil, dbErr("list workspaces", err)
54		}
55	
56		out := make([]domain.WorkspaceSummary, 0, len(rows))
57		for _, r := range rows {
58			latestRun, _ := a.q.GetLatestSyncRun(ctx, r.ID) //nolint:errcheck
59			ss := syncRunToSourceState(&latestRun, nil)
60	
61			out = append(out, domain.WorkspaceSummary{
62				ID:          uuidStr(r.ID),
63				Name:        r.Name,
64				Slug:        r.Slug,
65				RepoURL:     githubRepoURL(ctx, a.q, r.ID),
66				SourceState: ss,
67				UpdatedAt:   r.UpdatedAt.Time,
68			})
69		}
70		return out, nil
71	}
