73	// GetWorkspace returns the full workspace detail.
74	func (a *Adapter) GetWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, error) {
75		uid, err := parseUUID(workspaceID)
76		if err != nil {
77			return nil, err
78		}
79	
80		ws, err := a.q.GetWorkspace(ctx, uid)
81		if err != nil {
82			if errors.Is(err, pgx.ErrNoRows) {
83				return nil, domain.NewDatabaseError(domain.ErrDatabaseNotFound, "workspace not found: "+workspaceID)
84			}
85			return nil, dbErr("get workspace", err)
86		}
87	
88		features, err := a.q.ListWorkspaceFeatures(ctx, uid)
89		if err != nil {
90			return nil, dbErr("list features", err)
91		}
92	
93		tasks, err := a.q.ListWorkspaceTasks(ctx, uid)
94		if err != nil {
95			return nil, dbErr("list tasks", err)
96		}
97	
98		latestRun, _ := a.q.GetLatestSyncRun(ctx, uid) //nolint:errcheck
99		ss := syncRunToSourceState(&latestRun, nil)
100	
101		featureSummaries := make([]domain.FeatureSummary, 0, len(features))
102		for _, f := range features {
103			featureSummaries = append(featureSummaries, rowToFeatureSummary(f, tasks))
104		}
105	
106		taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
107		for _, t := range tasks {
108			taskSummaries = append(taskSummaries, rowToTaskSummary(t))
109		}
110	
111		return &domain.WorkspaceDetail{
112			WorkspaceSummary: domain.WorkspaceSummary{
113				ID:          workspaceID,
114				Name:        ws.Name,
115				Slug:        ws.Slug,
116				RepoURL:     githubRepoURL(ctx, a.q, uid),
117				SourceState: ss,
118				UpdatedAt:   ws.UpdatedAt.Time,
119			},
120			Features: featureSummaries,
121			Tasks:    taskSummaries,
122		}, nil
123	}
