125	// GetFeature returns the full feature detail.
126	func (a *Adapter) GetFeature(ctx context.Context, workspaceID, featureID string) (*domain.FeatureDetail, error) {
127		uid, err := parseUUID(workspaceID)
128		if err != nil {
129			return nil, err
130		}
131	
132		f, err := a.q.GetWorkspaceFeature(ctx, database.GetWorkspaceFeatureParams{
133			WorkspaceID: uid,
134			FeatureID:   featureID,
135		})
136		if err != nil {
137			if errors.Is(err, pgx.ErrNoRows) {
138				return nil, domain.NewDatabaseError(domain.ErrDatabaseNotFound, "feature not found: "+featureID)
139			}
140			return nil, dbErr("get feature", err)
141		}
142	
143		docs, err := a.q.ListFeatureDocuments(ctx, database.ListFeatureDocumentsParams{
144			WorkspaceID: uid,
145			FeatureID:   featureID,
146		})
147		if err != nil {
148			return nil, dbErr("list feature documents", err)
149		}
150	
151		tasks, err := a.q.ListFeatureTasks(ctx, database.ListFeatureTasksParams{
152			WorkspaceID: uid,
153			FeatureID:   featureID,
154		})
155		if err != nil {
156			return nil, dbErr("list feature tasks", err)
157		}
158	
159		actEvents, err := a.q.ListFeatureActivityEvents(ctx, database.ListFeatureActivityEventsParams{
160			WorkspaceID: uid,
161			FeatureID:   featureID,
162		})
163		if err != nil {
164			return nil, dbErr("list feature activity", err)
165		}
166	
167		latestRun, _ := a.q.GetLatestSyncRun(ctx, uid) //nolint:errcheck
168		ss := syncRunToSourceState(&latestRun, nil)
169	
170		allTasks, _ := a.q.ListWorkspaceTasks(ctx, uid) //nolint:errcheck
171		summary := rowToFeatureSummary(f, allTasks)
172	
173		docLinks := make([]domain.DocumentLink, 0, len(docs))
174		for _, d := range docs {
175			dl := domain.DocumentLink{
176				DocumentType: d.DocumentType,
177				SourcePath:   d.SourcePath,
178			}
179			if d.URL != nil {
180				dl.URL = *d.URL
181			}
182			docLinks = append(docLinks, dl)
183		}
184	
185		taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
186		for _, t := range tasks {
187			taskSummaries = append(taskSummaries, rowToTaskSummary(t))
188		}
189	
190		activity := make([]domain.ActivityEvent, 0, len(actEvents))
191		for _, e := range actEvents {
192			activity = append(activity, rowToActivityEvent(e))
193		}
194	
195		return &domain.FeatureDetail{
196			FeatureSummary: summary,
197			WorkspaceID:    workspaceID,
198			Documents:      docLinks,
199			Tasks:          taskSummaries,
200			Activity:       activity,
201			SourceState:    ss,
202		}, nil
203	}
