205	// GetTask returns the full task detail.
206	func (a *Adapter) GetTask(ctx context.Context, workspaceID, taskID string) (*domain.TaskDetail, error) {
207		uid, err := parseUUID(workspaceID)
208		if err != nil {
209			return nil, err
210		}
211	
212		t, err := a.q.GetWorkspaceTask(ctx, database.GetWorkspaceTaskParams{
213			WorkspaceID: uid,
214			TaskID:      taskID,
215		})
216		if err != nil {
217			if errors.Is(err, pgx.ErrNoRows) {
218				return nil, domain.NewDatabaseError(domain.ErrDatabaseNotFound, "task not found: "+taskID)
219			}
220			return nil, dbErr("get task", err)
221		}
222	
223		var featureID string
224		if t.FeatureID != "" {
225			featureID = t.FeatureID
226		}
227	
228		actEvents, _ := a.q.ListTaskActivityEvents(ctx, database.ListTaskActivityEventsParams{ //nolint:errcheck
229			WorkspaceID: uid,
230			FeatureID:   featureID,
231			TaskID:      taskID,
232		})
233	
234		activity := make([]domain.ActivityEvent, 0, len(actEvents))
235		for _, e := range actEvents {
236			activity = append(activity, rowToActivityEvent(e))
237		}
238	
239		return &domain.TaskDetail{
240			TaskSummary: rowToTaskSummary(t),
241			WorkspaceID: workspaceID,
242			DependsOn:   unmarshalStringSlice(t.DependsOn),
243			Execution:   unmarshalExecution(t.Execution),
244			Activity:    activity,
245		}, nil
246	}
