270	// ListActivity returns activity events filtered by the given scope.
271	func (a *Adapter) ListActivity(ctx context.Context, workspaceID string, scope domain.ActivityScope) ([]domain.ActivityEvent, error) {
272		uid, err := parseUUID(workspaceID)
273		if err != nil {
274			return nil, err
275		}
276	
277		var rows []database.WorkspaceActivityEvent
278		var queryErr error
279	
280		switch {
281		case scope.FeatureID != "" && scope.TaskID != "":
282			rows, queryErr = a.q.ListTaskActivityEvents(ctx, database.ListTaskActivityEventsParams{
283				WorkspaceID: uid,
284				FeatureID:   scope.FeatureID,
285				TaskID:      scope.TaskID,
286			})
287		case scope.FeatureID != "":
288			rows, queryErr = a.q.ListFeatureActivityEvents(ctx, database.ListFeatureActivityEventsParams{
289				WorkspaceID: uid,
290				FeatureID:   scope.FeatureID,
291			})
292		default:
293			rows, queryErr = a.q.ListActivityEvents(ctx, uid)
294		}
295	
296		if queryErr != nil {
297			return nil, dbErr("list activity", queryErr)
298		}
299	
300		out := make([]domain.ActivityEvent, 0, len(rows))
301		for _, r := range rows {
302			out = append(out, rowToActivityEvent(r))
303		}
304		return out, nil
