307	// SaveSnapshot upserts all core tables from the given snapshot inside a single transaction.
308	func (a *Adapter) SaveSnapshot(ctx context.Context, workspaceID string, snapshot *domain.WorkspaceSnapshot) error {
309		uid, err := parseUUID(workspaceID)
310		if err != nil {
311			return err
312		}
313	
314		tx, err := a.pool.BeginTx(ctx, pgx.TxOptions{})
315		if err != nil {
316			return fmt.Errorf("begin transaction: %w", err)
317		}
318		defer tx.Rollback(ctx) //nolint:errcheck
319	
320		if err := upsertSnapshot(ctx, a.q.WithTx(tx), uid, snapshot); err != nil {
321			return err
322		}
323		return tx.Commit(ctx)
324	}
