326	// GetActiveSnapshot returns the latest WorkspaceSnapshot reconstructed from core tables.
327	func (a *Adapter) GetActiveSnapshot(ctx context.Context, workspaceID string) (*domain.WorkspaceSnapshot, error) {
328		uid, err := parseUUID(workspaceID)
329		if err != nil {
330			return nil, err
331		}
332	
333		ws, err := a.q.GetWorkspace(ctx, uid)
334		if err != nil {
335			if errors.Is(err, pgx.ErrNoRows) {
336				return nil, nil
337			}
338			return nil, dbErr("get workspace", err)
339		}
340	
341		features, err := a.q.ListWorkspaceFeatures(ctx, uid)
342		if err != nil {
343			return nil, dbErr("list features for snapshot", err)
344		}
345	
346		repos, err := a.q.ListWorkspaceRepos(ctx, uid)
347		if err != nil {
348			return nil, dbErr("list repos for snapshot", err)
349		}
350	
351		src, _ := a.q.GetGitHubSource(ctx, uid) //nolint:errcheck
352	
353		featureSnapshots := make([]domain.FeatureSnapshot, 0, len(features))
354		for _, f := range features {
355			fs, err := buildFeatureSnapshot(ctx, a.q, uid, f)
356			if err != nil {
357				return nil, err
358			}
359			featureSnapshots = append(featureSnapshots, fs)
360		}
361	
362		repoEntries := make([]domain.RepoEntry, 0, len(repos))
363		for _, r := range repos {
364			re := domain.RepoEntry{RepoID: r.RepoID}
365			if r.BaseBranch != nil {
366				re.BaseBranch = *r.BaseBranch
367			}
368			repoEntries = append(repoEntries, re)
369		}
370	
371		repoURL := ""
372		if src.RepoURL != "" {
373			repoURL = src.RepoURL
374		}
375	
376		return &domain.WorkspaceSnapshot{
377			WorkspaceID: workspaceID,
378			Name:        ws.Name,
379			Slug:        ws.Slug,
380			RepoURL:     repoURL,
381			Features:    featureSnapshots,
382			Repos:       repoEntries,
383		}, nil
384	}
