403	// upsertSnapshot is the transactional core of SaveSnapshot.
404	func upsertSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, snap *domain.WorkspaceSnapshot) error {
405		// Upsert workspace record (slug is the natural key).
406		_, err := q.UpsertWorkspace(ctx, database.UpsertWorkspaceParams{
407			ID:               uid,
408			Slug:             snap.Slug,
409			Name:             snap.Name,
410			ManagementRepoID: "management-repo",
411		})
412		if err != nil {
413			return fmt.Errorf("upsert workspace: %w", err)
414		}
415	
416		// Upsert repos.
417		repoIDs := make([]string, 0, len(snap.Repos))
418		for _, r := range snap.Repos {
419			bp := ptrStr(r.BaseBranch)
420			_, err := q.UpsertWorkspaceRepo(ctx, database.UpsertWorkspaceRepoParams{
421				WorkspaceID: uid,
422				RepoID:      r.RepoID,
423				BaseBranch:  bp,
424			})
425			if err != nil {
426				return fmt.Errorf("upsert repo %s: %w", r.RepoID, err)
427			}
428			repoIDs = append(repoIDs, r.RepoID)
429		}
430		if err := q.DeleteWorkspaceReposNotIn(ctx, database.DeleteWorkspaceReposNotInParams{
431			WorkspaceID: uid,
432			RepoIds:     repoIDs,
433		}); err != nil {
434			return fmt.Errorf("delete stale repos: %w", err)
435		}
436	
437		// Upsert features, docs, tasks, activity.
438		featureIDs := make([]string, 0, len(snap.Features))
439		for _, f := range snap.Features {
440			if err := upsertFeatureSnapshot(ctx, q, uid, f); err != nil {
441				return err
442			}
443			featureIDs = append(featureIDs, f.FeatureID)
444		}
445		if err := q.DeleteWorkspaceFeaturesNotIn(ctx, database.DeleteWorkspaceFeaturesNotInParams{
446			WorkspaceID: uid,
447			FeatureIds:  featureIDs,
448		}); err != nil {
449			return fmt.Errorf("delete stale features: %w", err)
450		}
451	
452		return nil
453	}
