455	func upsertFeatureSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, f domain.FeatureSnapshot) error {
456		stages, _ := json.Marshal(nil) //nolint:errcheck
457		_, err := q.UpsertWorkspaceFeature(ctx, database.UpsertWorkspaceFeatureParams{
458			WorkspaceID:   uid,
459			FeatureID:     f.FeatureID,
460			Title:         f.Title,
461			FeatureStatus: ptrStr(f.Status),
462			CurrentStage:  ptrStr(f.CurrentStage),
463			NextAction:    ptrStr(f.NextAction),
464			Stages:        stages,
465			SourcePath:    f.SourcePath,
466			SourceHash:    ptrStr(f.SourceHash),
467		})
468		if err != nil {
469			return fmt.Errorf("upsert feature %s: %w", f.FeatureID, err)
470		}
471	
472		// Upsert documents.
473		docTypes := make([]string, 0, len(f.Documents))
474		for _, d := range f.Documents {
475			_, err := q.UpsertFeatureDocument(ctx, database.UpsertFeatureDocumentParams{
476				WorkspaceID:  uid,
477				FeatureID:    f.FeatureID,
478				DocumentType: d.DocumentType,
479				SourcePath:   d.SourcePath,
480				URL:          ptrStr(d.URL),
481			})
482			if err != nil {
483				return fmt.Errorf("upsert document %s/%s: %w", f.FeatureID, d.DocumentType, err)
484			}
485			docTypes = append(docTypes, d.DocumentType)
486		}
487		if err := q.DeleteFeatureDocumentsNotIn(ctx, database.DeleteFeatureDocumentsNotInParams{
488			WorkspaceID:   uid,
489			FeatureID:     f.FeatureID,
490			DocumentTypes: docTypes,
491		}); err != nil {
492			return fmt.Errorf("delete stale documents for %s: %w", f.FeatureID, err)
493		}
494	
495		// Upsert tasks.
496		taskIDs := make([]string, 0, len(f.Tasks))
497		for _, t := range f.Tasks {
498			if err := upsertTaskSnapshot(ctx, q, uid, f.FeatureID, t); err != nil {
499				return err
500			}
501			taskIDs = append(taskIDs, t.TaskID)
502		}
503		if err := q.DeleteFeatureTasksNotIn(ctx, database.DeleteFeatureTasksNotInParams{
504			WorkspaceID: uid,
505			FeatureID:   f.FeatureID,
506			TaskIds:     taskIDs,
507		}); err != nil {
508			return fmt.Errorf("delete stale tasks for %s: %w", f.FeatureID, err)
509		}
510	
511		// Upsert feature-level activity (task_id = nil).
512		if err := upsertFeatureActivity(ctx, q, uid, f); err != nil {
513			return err
514		}
515	
516		return nil
517	}
