519	func upsertTaskSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, featureID string, t domain.TaskSnapshot) error {
520		dependsOn, _ := json.Marshal(t.DependsOn) //nolint:errcheck
521		execution, _ := json.Marshal(t.Execution) //nolint:errcheck
522		pr, _ := json.Marshal(t.PR)               //nolint:errcheck
523		wsPr, _ := json.Marshal(t.WorkspacePR)    //nolint:errcheck
524	
525		_, err := q.UpsertWorkspaceTask(ctx, database.UpsertWorkspaceTaskParams{
526			WorkspaceID:   uid,
527			FeatureID:     featureID,
528			TaskID:        t.TaskID,
529			Title:         t.Title,
530			Repo:          ptrStr(t.Repo),
531			Status:        ptrStr(t.Status),
532			DependsOn:     dependsOn,
533			BlockedReason: ptrStr(t.BlockedReason),
534			Branch:        ptrStr(t.Branch),
535			Execution:     execution,
536			Pr:            pr,
537			WorkspacePr:   wsPr,
538			SourcePath:    t.SourcePath,
539			SourceHash:    ptrStr(t.SourceHash),
540		})
541		if err != nil {
542			return fmt.Errorf("upsert task %s/%s: %w", featureID, t.TaskID, err)
543		}
544	
545		// Upsert task-level activity from the task log.
546		if err := upsertTaskActivity(ctx, q, uid, featureID, t); err != nil {
547			return err
548		}
549	
550		return nil
551	}
