553	// upsertFeatureActivity normalizes feature-level activity events (scope_type=feature, task_id=NULL).
554	// Uses the partial unique index on (workspace_id, feature_id, sequence) WHERE task_id IS NULL.
555	func upsertFeatureActivity(ctx context.Context, q *database.Queries, uid pgtype.UUID, f domain.FeatureSnapshot) error {
556		for i, evt := range f.Activity {
557			raw, _ := json.Marshal(evt) //nolint:errcheck
558			_, err := q.UpsertFeatureActivityEvent(ctx, database.UpsertFeatureActivityEventParams{
559				WorkspaceID: uid,
560				ScopeType:   "feature",
561				FeatureID:   f.FeatureID,
562				Action:      ptrStr(evt.Action),
563				Actor:       ptrStr(evt.Actor),
564				OccurredAt:  ptrStr(evt.OccurredAt.Format(time.RFC3339)),
565				Note:        ptrStr(evt.Note),
566				Sequence:    int32(i),
567				RawEvent:    raw,
568			})
569			if err != nil {
570				return fmt.Errorf("upsert feature activity %s[%d]: %w", f.FeatureID, i, err)
571			}
572		}
573		return nil
574	}
