576	// upsertTaskActivity normalizes task log entries (scope_type=task).
577	// Uses the partial unique index on (workspace_id, feature_id, task_id, sequence) WHERE task_id IS NOT NULL.
578	func upsertTaskActivity(ctx context.Context, q *database.Queries, uid pgtype.UUID, featureID string, t domain.TaskSnapshot) error {
579		for i, evt := range t.Activity {
580			raw, _ := json.Marshal(evt) //nolint:errcheck
581			_, err := q.UpsertTaskActivityEvent(ctx, database.UpsertTaskActivityEventParams{
582				WorkspaceID: uid,
583				ScopeType:   "task",
584				FeatureID:   featureID,
585				TaskID:      t.TaskID,
586				Action:      ptrStr(evt.Action),
587				Actor:       ptrStr(evt.Actor),
588				OccurredAt:  ptrStr(evt.OccurredAt.Format(time.RFC3339)),
589				Note:        ptrStr(evt.Note),
590				Sequence:    int32(i),
591				RawEvent:    raw,
592			})
593			if err != nil {
594				return fmt.Errorf("upsert task activity %s/%s[%d]: %w", featureID, t.TaskID, i, err)
595			}
596		}
597		return nil
598	}
