600	// buildFeatureSnapshot reconstructs a FeatureSnapshot from the database rows.
601	func buildFeatureSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, f database.WorkspaceFeature) (domain.FeatureSnapshot, error) {
602		docs, err := q.ListFeatureDocuments(ctx, database.ListFeatureDocumentsParams{
603			WorkspaceID: uid,
604			FeatureID:   f.FeatureID,
605		})
606		if err != nil {
607			return domain.FeatureSnapshot{}, dbErr("list docs for snapshot", err)
608		}
609	
610		tasks, err := q.ListFeatureTasks(ctx, database.ListFeatureTasksParams{
611			WorkspaceID: uid,
612			FeatureID:   f.FeatureID,
613		})
614		if err != nil {
615			return domain.FeatureSnapshot{}, dbErr("list tasks for snapshot", err)
616		}
617	
618		docSnaps := make([]domain.DocumentSnapshot, 0, len(docs))
619		for _, d := range docs {
620			ds := domain.DocumentSnapshot{
621				DocumentType: d.DocumentType,
622				SourcePath:   d.SourcePath,
623			}
624			if d.URL != nil {
625				ds.URL = *d.URL
626			}
627			docSnaps = append(docSnaps, ds)
628		}
629	
630		taskSnaps := make([]domain.TaskSnapshot, 0, len(tasks))
631		for _, t := range tasks {
632			taskSnaps = append(taskSnaps, rowToTaskSnapshot(t))
633		}
634	
635		fs := domain.FeatureSnapshot{
636			FeatureID:  f.FeatureID,
637			Title:      f.Title,
638			SourcePath: f.SourcePath,
639			Documents:  docSnaps,
640			Tasks:      taskSnaps,
641		}
642		if f.FeatureStatus != nil {
643			fs.Status = *f.FeatureStatus
644		}
645		if f.CurrentStage != nil {
646			fs.CurrentStage = *f.CurrentStage
647		}
648		if f.NextAction != nil {
649			fs.NextAction = *f.NextAction
650		}
651		if f.SourceHash != nil {
652			fs.SourceHash = *f.SourceHash
653		}
654		return fs, nil
655	}
656	
657	// rowToTaskSnapshot converts a database row to a domain.TaskSnapshot.
658	func rowToTaskSnapshot(t database.WorkspaceTask) domain.TaskSnapshot {
659		ts := domain.TaskSnapshot{
660			TaskID:     t.TaskID,
661			FeatureID:  t.FeatureID,
662			Title:      t.Title,
663			SourcePath: t.SourcePath,
664		}
665		if t.Repo != nil {
666			ts.Repo = *t.Repo
667		}
668		if t.Status != nil {
669			ts.Status = *t.Status
670		}
671		if t.BlockedReason != nil {
672			ts.BlockedReason = *t.BlockedReason
673		}
674		if t.Branch != nil {
675			ts.Branch = *t.Branch
676		}
677		if t.SourceHash != nil {
678			ts.SourceHash = *t.SourceHash
679		}
680		ts.DependsOn = unmarshalStringSlice(t.DependsOn)
681		if len(t.Execution) > 0 {
682			var m map[string]interface{}
683			_ = json.Unmarshal(t.Execution, &m)
684			ts.Execution = m
685		}
686		if len(t.Pr) > 0 {
687			var m map[string]interface{}
688			_ = json.Unmarshal(t.Pr, &m)
689			ts.PR = m
690		}
691		if len(t.WorkspacePr) > 0 {
692			var m map[string]interface{}
693			_ = json.Unmarshal(t.WorkspacePr, &m)
694			ts.WorkspacePR = m
695		}
696		return ts
697	}
698	
699	// rowToFeatureSummary converts feature row + task list to a domain.FeatureSummary.
700	func rowToFeatureSummary(f database.WorkspaceFeature, tasks []database.WorkspaceTask) domain.FeatureSummary {
701		counts := domain.TaskCounts{}
702		for _, t := range tasks {
703			if t.FeatureID != f.FeatureID {
704				continue
705			}
706			counts.Total++
707			if t.Status == nil {
708				continue
709			}
710			switch *t.Status {
711			case "done":
712				counts.Done++
713			case "in_progress":
714				counts.InProgress++
715			case "blocked":
716				counts.Blocked++
717			case "ready":
718				counts.Ready++
719			case "todo":
720				counts.Todo++
721			}
722		}
723	
724		fs := domain.FeatureSummary{
725			FeatureID:  f.FeatureID,
726			Title:      f.Title,
727			UpdatedAt:  f.UpdatedAt.Time,
728			TaskCounts: counts,
729		}
730		if f.FeatureStatus != nil {
731			fs.Status = *f.FeatureStatus
732		}
733		if f.CurrentStage != nil {
734			fs.CurrentStage = *f.CurrentStage
735		}
736		return fs
737	}
738	
739	// rowToTaskSummary converts a workspace_tasks row to domain.TaskSummary.
740	func rowToTaskSummary(t database.WorkspaceTask) domain.TaskSummary {
741		ts := domain.TaskSummary{
742			TaskID:    t.TaskID,
743			FeatureID: t.FeatureID,
744			Title:     t.Title,
745		}
746		if t.Status != nil {
747			ts.Status = *t.Status
748		}
749		if t.Repo != nil {
750			ts.Repo = *t.Repo
751		}
752		if t.Branch != nil {
753			ts.Branch = *t.Branch
754		}
755		if t.BlockedReason != nil {
756			ts.BlockedReason = *t.BlockedReason
757			ts.IsBlocked = true
758		}
759		return ts
760	}
761	
762	// rowToActivityEvent converts a database row to domain.ActivityEvent.
763	func rowToActivityEvent(r database.WorkspaceActivityEvent) domain.ActivityEvent {
764		evt := domain.ActivityEvent{
765			Scope: r.ScopeType,
766		}
767		if r.Action != nil {
768			evt.Action = *r.Action
769		}
770		if r.Actor != nil {
771			evt.Actor = *r.Actor
772		}
773		if r.Note != nil {
774			evt.Note = *r.Note
775		}
776		if r.FeatureID != nil {
777			evt.FeatureID = *r.FeatureID
778		}
779		if r.TaskID != nil {
780			evt.TaskID = *r.TaskID
781		}
782		if r.OccurredAt != nil {
783			if t, err := time.Parse(time.RFC3339, *r.OccurredAt); err == nil {
784				evt.OccurredAt = t
785			}
786		}
787		return evt
788	}
789	
790	// syncRunRowToDomain converts a database sync run row to domain.SyncRun.
791	func syncRunRowToDomain(r database.WorkspaceSyncRun) *domain.SyncRun {
792		sr := &domain.SyncRun{
793			ID:          uuidStr(r.ID),
794			WorkspaceID: uuidStr(r.WorkspaceID),
795			Trigger:     r.Trigger,
796			Mode:        r.Mode,
797			Status:      domain.SyncStatus(r.Status),
798			StartedAt:   r.StartedAt.Time,
799		}
800		if r.CommitSha != nil {
801			sr.CommitSHA = *r.CommitSha
802		}
803		if r.ErrorCode != nil {
804			sr.ErrorCode = *r.ErrorCode
805		}
806		if r.ErrorMessage != nil {
807			sr.ErrorMsg = *r.ErrorMessage
808		}
809		if r.FinishedAt.Valid {
810			t := r.FinishedAt.Time
811			sr.FinishedAt = &t
812		}
813		return sr
814	}
815	
816	// syncRunToSourceState derives a SourceState from the latest sync run.
817	func syncRunToSourceState(r *database.WorkspaceSyncRun, threshold *time.Duration) domain.SourceState {
818		if r == nil || r.ID == (pgtype.UUID{}) {
819			return domain.StaleState(nil)
820		}
821		thr := domain.DefaultStaleThreshold
822		if threshold != nil {
823			thr = *threshold
824		}
825		return domain.DeriveSourceState(syncRunRowToDomain(*r), thr)
826	}
827	
828	// githubRepoURL fetches the repo URL from workspace_github_sources (best-effort).
829	func githubRepoURL(ctx context.Context, q *database.Queries, uid pgtype.UUID) string {
830		src, err := q.GetGitHubSource(ctx, uid)
831		if err != nil {
832			return ""
833		}
834		return src.RepoURL
835	}
836	
837	// parseUUID parses a plain UUID string into pgtype.UUID.
838	func parseUUID(s string) (pgtype.UUID, error) {
839		var uid pgtype.UUID
840		if err := uid.Scan(s); err != nil {
841			return pgtype.UUID{}, domain.NewValidationError(domain.ErrValidationMissingInput, "invalid workspace id: "+s)
842		}
843		return uid, nil
844	}
845	
846	// uuidStr renders a pgtype.UUID as a lowercase hyphenated string.
847	func uuidStr(u pgtype.UUID) string {
848		if !u.Valid {
849			return ""
850		}
851		b := u.Bytes
852		return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
853			b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
854	}
855	
856	// ptrStr returns nil if s is empty, otherwise returns &s.
857	func ptrStr(s string) *string {
858		if s == "" {
859			return nil
860		}
861		return &s
862	}
863	
864	// unmarshalStringSlice decodes a JSON array of strings.
865	func unmarshalStringSlice(raw json.RawMessage) []string {
866		if len(raw) == 0 {
867			return nil
868		}
869		var out []string
870		_ = json.Unmarshal(raw, &out)
871		return out
872	}
873	
874	// unmarshalExecution decodes execution JSON into domain.ExecutionContext.
875	func unmarshalExecution(raw json.RawMessage) domain.ExecutionContext {
876		if len(raw) == 0 {
877			return domain.ExecutionContext{}
878		}
879		var ec domain.ExecutionContext
880		_ = json.Unmarshal(raw, &ec)
881		return ec
882	}
883	
884	// dbErr wraps a database error in a domain SourceError.
885	func dbErr(op string, err error) error {
886		if strings.Contains(err.Error(), "no rows") {
887			return domain.NewDatabaseError(domain.ErrDatabaseNotFound, op+": not found")
888		}
889		return domain.NewDatabaseError(domain.ErrDatabaseQuery, op+": "+err.Error())
890	}
