16	// timestampFormats lists the timestamp formats found in task/feature YAML files.
17	// Task YAML files use offsets without colons (e.g. +0700, +0000); RFC3339 requires
18	// colons (e.g. +07:00). We try both.
19	var timestampFormats = []string{
20		time.RFC3339Nano,
21		time.RFC3339,
22		"2006-01-02T15:04:05-0700", // no colon in offset
23		"2006-01-02T15:04:05.999999999-0700",
24		"2006-01-02T15:04:05Z0700", // Z or numeric offset
25	}
