27	// parseTimestamp attempts to parse a timestamp string using known formats.
28	// Returns zero time if parsing fails — callers treat zero as "unknown".
29	func parseTimestamp(s string) time.Time {
30		s = strings.TrimSpace(s)
31		if s == "" {
32			return time.Time{}
33		}
34		for _, f := range timestampFormats {
35			if t, err := time.Parse(f, s); err == nil {
36				return t.UTC()
37			}
38		}
39		return time.Time{}
40	}
