1	// Package github implements the GitHubWorkspaceAdapter interface.
2	// It uses the Git Trees API for feature discovery and the Contents API for
3	// individual file fetches — a single request discovers all feature paths,
4	// and only the relevant files are read. No archive download or zip extraction
5	// is required, and the same approach works for both full reconciliation and
6	// targeted sync.
7	package github
8	
9	import (
10		"context"
11		"fmt"
12		"net/url"
13		"os"
14		"strings"
15		"time"
16	
17		"github.com/tiendv89/workspace-github-adapter/internal/domain"
18	)
19	
20	// Adapter implements domain.GitHubWorkspaceAdapter.
21	type Adapter struct {
22		token string
23	}
24	
25	// New creates a new Adapter. If token is empty, the GITHUB_TOKEN environment
26	// variable is used as a fallback.
27	func New(token string) *Adapter {
28		if token == "" {
29			token = os.Getenv("GITHUB_TOKEN")
30		}
31		return &Adapter{token: token}
32	}
33	
34	// Ensure Adapter satisfies the interface at compile time.
35	var _ domain.GitHubWorkspaceAdapter = (*Adapter)(nil)
36	
37	// ImportWorkspace performs a full reconciliation import of the given repository.
38	func (a *Adapter) ImportWorkspace(ctx context.Context, input domain.ImportInput) (*domain.WorkspaceSnapshot, error) {
39		if err := validateInput(input); err != nil {
40			return nil, *err
41		}
42	
43		token := input.Token
44		if token == "" {
45			token = a.token
46		}
47		c := newClient(token)
48	
49		owner, repo, err := parseRepoURL(input.RepoURL)
50		if err != nil {
51			return nil, *err
52		}
53	
54		ref := input.DefaultBranch
55		if ref == "" {
56			ref = "main"
57		}
58	
59		return a.fetchSnapshot(ctx, c, owner, repo, ref, "")
60	}
61	
62	// SyncWorkspace re-fetches the repository at the given ref and returns an updated snapshot.
63	func (a *Adapter) SyncWorkspace(ctx context.Context, workspaceID, repoURL, ref string) (*domain.WorkspaceSnapshot, error) {
64		if repoURL == "" {
65			return nil, domain.NewValidationError(domain.ErrValidationMissingInput, "repoURL is required")
66		}
67		if ref == "" {
68			ref = "main"
69		}
70	
71		owner, repo, err := parseRepoURL(repoURL)
72		if err != nil {
73			return nil, *err
74		}
75	
76		c := newClient(a.token)
77		snap, fetchErr := a.fetchSnapshot(ctx, c, owner, repo, ref, workspaceID)
78		if fetchErr != nil {
79			return nil, fetchErr
80		}
81		return snap, nil
82	}
83	
84	// fetchSnapshot fetches the full workspace snapshot from GitHub.
85	func (a *Adapter) fetchSnapshot(ctx context.Context, c *client, owner, repo, ref, workspaceID string) (*domain.WorkspaceSnapshot, error) {
86		fetchedAt := time.Now().UTC()
87	
88		// Resolve the commit SHA for this ref.
89		commitSHA, err := c.getCommitSHA(ctx, owner, repo, ref)
90		if err != nil {
91			return nil, mapFetchError(err, owner, repo)
92		}
93	
94		// Fetch the full file tree in one request (Git Trees API, recursive=1).
95		// Pass commitSHA directly so getTree doesn't need to re-resolve the ref.
96		tree, err := c.getTree(ctx, owner, repo, commitSHA)
97		if err != nil {
98			return nil, mapFetchError(err, owner, repo)
99		}
100	
101		// Build a path-set for quick existence checks.
102		pathSet := make(map[string]struct{}, len(tree.Tree))
103		for _, e := range tree.Tree {
104			if e.Type == "blob" {
105				pathSet[e.Path] = struct{}{}
106			}
107		}
108	
109		// Fetch and parse workspace.yaml (required).
110		wsYAMLPath := "workspace.yaml"
111		wsData, err := c.getFileContent(ctx, owner, repo, wsYAMLPath, ref)
112		if err != nil {
113			return nil, mapFetchError(err, owner, repo)
114		}
115		if wsData == nil {
116			return nil, domain.SourceError{
117				Code:      domain.ErrGitHubNotFound,
118				Message:   fmt.Sprintf("required file not found: %s", wsYAMLPath),
119				Source:    domain.ErrorSourceGitHub,
120				Retryable: false,
121				Path:      wsYAMLPath,
122			}
123		}
124		wsCfg, parseErr := parseWorkspaceYAML(wsData, wsYAMLPath)
125		if parseErr != nil {
126			return nil, *parseErr
127		}
128	
129		// Discover feature directories from the tree.
130		featureIDs := discoverFeatureIDs(tree.Tree)
131	
132		// Map repos from workspace.yaml.
133		repos := make([]domain.RepoEntry, 0, len(wsCfg.Repos))
134		for _, r := range wsCfg.Repos {
135			repos = append(repos, domain.RepoEntry{
136				RepoID:     r.ID,
137				BaseBranch: r.BaseBranch,
138			})
139		}
140	
141		name := wsCfg.Name
142		if name == "" {
143			name = owner + "/" + repo
144		}
145		slug := slugify(name)
146		if workspaceID == "" {
147			workspaceID = slug
148		}
149	
150		var sourceErrors []domain.SourceError
151		features := make([]domain.FeatureSnapshot, 0, len(featureIDs))
152	
153		for _, featureID := range featureIDs {
154			feat, errs := a.fetchFeature(ctx, c, owner, repo, ref, featureID, pathSet)
155			sourceErrors = append(sourceErrors, errs...)
156			if feat != nil {
157				features = append(features, *feat)
158			}
159		}
160	
161		return &domain.WorkspaceSnapshot{
162			WorkspaceID:  workspaceID,
163			Name:         name,
164			Slug:         slug,
165			RepoURL:      "https://github.com/" + owner + "/" + repo,
166			CommitSHA:    commitSHA,
167			FetchedAt:    fetchedAt,
168			Features:     features,
169			Repos:        repos,
170			SourceErrors: sourceErrors,
171		}, nil
172	}
173	
174	// fetchFeature fetches and parses all artifacts for a single feature.
175	func (a *Adapter) fetchFeature(ctx context.Context, c *client, owner, repo, ref, featureID string, pathSet map[string]struct{}) (*domain.FeatureSnapshot, []domain.SourceError) {
176		var errs []domain.SourceError
177	
178		docPaths := featureDocPaths(featureID)
179		statusPath := docPaths["status_yaml"]
180	
181		// status.yaml is required — if missing, emit a source error.
182		statusData, err := c.getFileContent(ctx, owner, repo, statusPath, ref)
183		if err != nil {
184			errs = append(errs, asSourceError(err, statusPath))
185			return nil, errs
186		}
187		if statusData == nil {
188			errs = append(errs, domain.SourceError{
189				Code:      domain.ErrGitHubNotFound,
190				Message:   fmt.Sprintf("required file not found: %s", statusPath),
191				Source:    domain.ErrorSourceGitHub,
192				Retryable: false,
193				Path:      statusPath,
194			})
195			return nil, errs
196		}
197	
198		status, parseErr := parseFeatureStatusYAML(statusData, statusPath)
199		if parseErr != nil {
200			errs = append(errs, *parseErr)
201			return nil, errs
202		}
203	
204		// Build document links — only status.yaml has required content; the rest are optional.
205		docs := []domain.DocumentSnapshot{}
206		for docType, docPath := range docPaths {
207			_, exists := pathSet[docPath]
208			if exists || docType == "status_yaml" {
209				docs = append(docs, domain.DocumentSnapshot{
210					DocumentType: docType,
211					SourcePath:   docPath,
212					URL:          buildWebURL(owner, repo, ref, docPath),
213				})
214			}
215		}
216	
217		// Fetch all task YAMLs for this feature.
218		tasksDir := "docs/features/" + featureID + "/tasks/"
219		var taskSnapshots []domain.TaskSnapshot
220		for p := range pathSet {
221			if !strings.HasPrefix(p, tasksDir) {
222				continue
223			}
224			taskID := taskFileBase(p)
225			if taskID == "" {
226				continue
227			}
228			taskData, err := c.getFileContent(ctx, owner, repo, p, ref)
229			if err != nil {
230				errs = append(errs, asSourceError(err, p))
231				continue
232			}
233			if taskData == nil {
234				continue
235			}
236			taskParsed, parseErr := parseTaskYAML(taskData, p)
237			if parseErr != nil {
238				errs = append(errs, *parseErr)
239				continue
240			}
241	
242			taskSnap := mapTaskSnapshot(taskParsed, featureID, taskID, p, taskData)
243			taskSnapshots = append(taskSnapshots, taskSnap)
244		}
245	
246		// Map feature history to activity events.
247		activity := mapActivityLog(status.History, "feature", featureID, "")
248	
249		return &domain.FeatureSnapshot{
250			FeatureID:    featureID,
251			Title:        status.Title,
252			Status:       status.Status,
253			CurrentStage: status.Stage,
254			NextAction:   status.NextAction,
255			SourcePath:   statusPath,
256			SourceHash:   hashContent(statusData),
257			Documents:    docs,
258			Tasks:        taskSnapshots,
259			Activity:     activity,
260		}, errs
261	}
262	
263	// mapTaskSnapshot converts a parsed taskYAML to a domain.TaskSnapshot.
264	func mapTaskSnapshot(t *taskYAML, featureID, taskID, sourcePath string, rawData []byte) domain.TaskSnapshot {
265		var activity []domain.ActivityEvent
266		if len(t.Log) > 0 {
267			activity = mapActivityLog(t.Log, "task", featureID, taskID)
268		}
269	
270		return domain.TaskSnapshot{
271			TaskID:        taskID,
272			FeatureID:     featureID,
273			Title:         t.Title,
274			Status:        t.Status,
275			Repo:          t.Repo,
276			Branch:        t.Branch,
277			DependsOn:     t.DependsOn,
278			BlockedReason: blockedReasonString(t.BlockedReason),
279			Execution:     t.Execution,
280			PR:            t.PR,
281			WorkspacePR:   t.WorkspacePR,
282			SourcePath:    sourcePath,
283			SourceHash:    hashContent(rawData),
284			Activity:      activity,
285		}
286	}
287	
288	// discoverFeatureIDs scans the tree entries for docs/features/*/status.yaml paths
289	// and returns the unique feature IDs found.
290	func discoverFeatureIDs(entries []treeEntry) []string {
291		seen := make(map[string]struct{})
292		var ids []string
293		for _, e := range entries {
294			if e.Type != "blob" {
295				continue
296			}
297			featureID, ok := extractFeatureID(e.Path)
298			if !ok {
299				continue
300			}
301			if _, dup := seen[featureID]; dup {
302				continue
303			}
304			seen[featureID] = struct{}{}
305			ids = append(ids, featureID)
306		}
307		return ids
308	}
309	
310	// validateInput checks ImportInput for required fields.
311	func validateInput(input domain.ImportInput) *domain.SourceError {
312		if input.RepoURL == "" {
313			se := domain.NewValidationError(domain.ErrValidationMissingInput, "RepoURL is required")
314			return &se
315		}
316		return nil
317	}
318	
319	// parseRepoURL extracts the owner and repo name from a GitHub URL.
320	// Accepts https://github.com/owner/repo and git@github.com:owner/repo.git forms.
321	func parseRepoURL(rawURL string) (owner, repo string, se *domain.SourceError) {
322		rawURL = strings.TrimSpace(rawURL)
323	
324		// SSH form: git@github.com:owner/repo.git
325		if strings.HasPrefix(rawURL, "git@github.com:") {
326			rest := strings.TrimPrefix(rawURL, "git@github.com:")
