37	func TestParseUUID_Invalid(t *testing.T) {
38		_, err := db.ExportedParseUUID("not-a-uuid")
39		if err == nil {
40			t.Fatal("expected error for invalid UUID, got nil")
41		}
42		var se domain.SourceError
43		if !errors.As(err, &se) {
44			t.Fatalf("expected domain.SourceError, got %T: %v", err, err)
45		}
46		if se.Code != domain.ErrValidationMissingInput {
47			t.Errorf("expected code %q, got %q", domain.ErrValidationMissingInput, se.Code)
48		}
49	}
