51	// TestPtrStr verifies pointer-or-nil semantics.
52	func TestPtrStr(t *testing.T) {
53		if got := db.ExportedPtrStr(""); got != nil {
54			t.Errorf("empty string should return nil, got %v", got)
55		}
56		s := "hello"
57		if got := db.ExportedPtrStr(s); got == nil || *got != s {
58			t.Errorf("non-empty string should return pointer to %q", s)
59		}
60	}
