62	// TestUnmarshalStringSlice verifies JSON array decoding.
63	func TestUnmarshalStringSlice(t *testing.T) {
64		cases := []struct {
65			name string
66			raw  string
67			want []string
68		}{
69			{"empty", `[]`, nil},
70			{"null", `null`, nil},
71			{"values", `["T1","T2"]`, []string{"T1", "T2"}},
72			{"empty bytes", ``, nil},
73		}
74		for _, tc := range cases {
75			t.Run(tc.name, func(t *testing.T) {
76				got := db.ExportedUnmarshalStringSlice(json.RawMessage(tc.raw))
77				if len(got) != len(tc.want) {
78					t.Fatalf("got %v, want %v", got, tc.want)
79				}
80				for i := range got {
81					if got[i] != tc.want[i] {
82						t.Errorf("[%d] got %q, want %q", i, got[i], tc.want[i])
83					}
84				}
85			})
86		}
