142		action := "claimed"
143		actor := "norepy@tiendv.dev"
144		note := "executor work phase begun"
145		fid := "my-feature"
146		tid := "T3"
147	
148		row := database.WorkspaceActivityEvent{
149			ScopeType:  "task",
150			FeatureID:  &fid,
151			TaskID:     &tid,
152			Action:     &action,
153			Actor:      &actor,
154			OccurredAt: &ts,
155			Note:       &note,
156			Sequence:   0,
157			RawEvent:   json.RawMessage(`{}`),
158		}
159	
160		got := db.ExportedRowToActivityEvent(row)
161	
162		if got.Action != action {
163			t.Errorf("Action: got %q, want %q", got.Action, action)
164		}
165		if got.Actor != actor {
166			t.Errorf("Actor: got %q, want %q", got.Actor, actor)
167		}
