170		}
171		if got.TaskID != tid {
172			t.Errorf("TaskID: got %q, want %q", got.TaskID, tid)
173		}
174		expectedTime, _ := time.Parse(time.RFC3339, ts)
175		if !got.OccurredAt.Equal(expectedTime) {
176			t.Errorf("OccurredAt: got %v, want %v", got.OccurredAt, expectedTime)
177		}
178	}
